S = "Hakeem Force Academy"
QS = [
(S, "In which region of Pakistan is the Shina (Sheena) language mainly spoken?", ["Gilgit-Baltistan", "Sindh", "Balochistan", "Southern Punjab"], 0, "Shina is the main language of the Gilgit area and nearby valleys of Gilgit-Baltistan. It belongs to the Dardic group of languages.", "Shina is also spoken in parts of Indian-administered Kashmir and in Kohistan.", [302, 2221, 570, 2211, 409, 2586]),
(S, "In which year was Colonel Sher Khan (Nishan-e-Haider) martyred?", ["1971", "1965", "1999", "1948"], 2, "Captain (later Colonel) Karnal Sher Khan was martyred in the Kargil conflict in July 1999. He was awarded the Nishan-e-Haider.", "He is the only Pakistan Army officer of Kargil to receive the Nishan-e-Haider.", [2300]),
(S, "In which city is the shrine of the Sufi poet Bulleh Shah located?", ["Multan", "Kasur", "Sialkot", "Pakpattan"], 1, "Bulleh Shah is buried in Kasur, in Punjab.", "Bulleh Shah wrote his Sufi poetry (kafis) in Punjabi.", [353]),
(S, "What is the value of sin 0 degrees?", ["1", "0", "0.5", "Undefined"], 1, "On the unit circle the point at angle 0 is (1, 0), and sine is the y value, which is 0.", "Cos 0 degrees is equal to 1.", [625]),
(S, "What is the value of sin 45 degrees?", ["1 divided by square root of 2", "1 divided by 2", "Square root of 3 divided by 2", "1"], 0, "In a right isosceles triangle with equal sides 1, the hypotenuse is square root of 2, so sin 45 is 1 divided by square root of 2, about 0.707.", "Cos 45 degrees has the same value as sin 45 degrees.", [2948]),
(S, "What is sin(270 degrees minus theta) equal to?", ["cos theta", "minus cos theta", "sin theta", "minus sin theta"], 1, "Sine of 270 minus theta lies in the third quadrant where sine is negative, and the function changes to cosine at 270. So the result is minus cos theta.", "Sin(90 minus theta) is equal to plus cos theta.", [626]),
(S, "What is the domain of the function sin x?", ["All real numbers", "Only x greater than 0", "From minus 1 to 1", "Only angles from 0 to 180 degrees"], 0, "Sine is defined for every real value of x. Its range, not its domain, is from minus 1 to 1.", "The period of sin x is 360 degrees (2 pi).", [1101]),
(S, "What is the determinant of a singular matrix?", ["1", "Minus 1", "0", "Infinity"], 2, "A square matrix is called singular exactly when its determinant is zero. Such a matrix has no inverse.", "A matrix with non-zero determinant is called non-singular and has an inverse.", [3091, 3092]),
(S, "Sidra is 6 years old and her brother is twice her age. How old will her brother be when Sidra becomes 11?", ["17", "22", "16", "18"], 0, "Brother is 6 x 2 = 12 now. Sidra becomes 11 after 5 years, so the brother will be 12 + 5 = 17.", "The age gap between two people always stays the same.", [1987]),
(S, "Ali is 6 years old and his sister is 2 times his age. What will his sister's age be when Ali is 8 years old?", ["16", "12", "14", "18"], 2, "Sister is 6 x 2 = 12 now. Ali becomes 8 after 2 years, so she will be 12 + 2 = 14.", "Here the sister is 6 years older than Ali, and the gap never changes.", [1548]),
(S, "If the sum of two angles of a triangle is 90 degrees, what is the third angle?", ["45 degrees", "60 degrees", "180 degrees", "90 degrees"], 3, "The three angles of a triangle add up to 180 degrees. So the third angle is 180 - 90 = 90 degrees.", "A triangle with one 90 degree angle is called a right-angled triangle.", [911]),
(S, "What is Sihah Sitta?", ["Six authentic collections of hadith", "Six pillars of faith", "Six divine books", "Six schools of Islamic law"], 0, "Sihah Sitta means the six most reliable books of hadith: Bukhari, Muslim, Abu Dawud, Tirmidhi, Nasai and Ibn Majah.", "Sahih Bukhari and Sahih Muslim are together called the Sahihain.", [2947]),
(S, "Why did Sir Syed Ahmad Khan receive the title of Sir?", ["He was knighted by the British Government in 1888 for his services", "He was elected president of the Muslim League", "He founded the city of Aligarh", "He won the Nobel Prize"], 0, "The British Government honoured him with a knighthood (KCSI) in 1888 in recognition of his public and educational services.", "He had earlier been given the title Javad-ud-Daula by the Mughal emperor.", [4831]),
(S, "What was the slogan of the Pakistan National Alliance (PNA) movement of 1977?", ["Roti, Kapra aur Makan", "Nizam-e-Mustafa", "Pakistan ka matlab kya", "Jeay Bhutto"], 1, "The PNA, an alliance of nine parties against Zulfikar Ali Bhutto, campaigned for the enforcement of the system of the Prophet (PBUH), called Nizam-e-Mustafa.", "The movement began after the March 1977 elections, and General Zia-ul-Haq imposed martial law on 5 July 1977.", [2048]),
(S, "Ship is to captain as car is to what?", ["Passenger", "Road", "Driver", "Engine"], 2, "A captain is the person who controls a ship. In the same way a driver controls a car.", "A pilot controls an aircraft.", [1004]),
(S, "Who won the Sir Garfield Sobers Trophy (ICC Men's Cricketer of the Year) for 2022?", ["Ben Stokes", "Babar Azam", "Virat Kohli", "Shaheen Shah Afridi"], 1, "Babar Azam scored 2598 runs in 44 matches in 2022 and won the award announced in January 2023.", "Shaheen Shah Afridi won the same trophy for 2021.", [2671, 4786]),
]
